import { describe, expect, it } from 'vitest';
import { forever, generate, num, onStart } from '../helpers';

describe('control blocks', () => {
  it('wraps the forever block in a while loop', () => {
    expect(
      generate([forever({ type: 'onboard_led', fields: { STATE: '1' } })]),
    ).toBe(
      [
        '# Code automatically generated by PicoBlocks',
        'from machine import Pin',
        '',
        'while True:',
        '    Pin("LED", Pin.OUT).value(1)',
        '',
      ].join('\n'),
    );
  });

  it('puts on start code above the loop', () => {
    expect(
      generate([
        onStart({ type: 'onboard_led', fields: { STATE: '1' } }),
        forever({ type: 'wait_seconds', inputs: { SECONDS: num(1) } }),
      ]),
    ).toBe(
      [
        '# Code automatically generated by PicoBlocks',
        'from machine import Pin',
        'import time',
        '',
        'Pin("LED", Pin.OUT).value(1)',
        '',
        'while True:',
        '    time.sleep(1)',
        '',
      ].join('\n'),
    );
  });

  it('generates pass for an empty forever loop', () => {
    expect(generate([{ type: 'forever' }])).toBe(
      [
        '# Code automatically generated by PicoBlocks',
        '',
        'while True:',
        '    pass',
        '',
      ].join('\n'),
    );
  });

  it('generates sleep for wait blocks', () => {
    const code = generate([
      forever(
        { type: 'wait_seconds', inputs: { SECONDS: num(0.5) } },
        { type: 'wait_milliseconds', inputs: { MS: num(250) } },
      ),
    ]);
    expect(code).toContain('    time.sleep(0.5)\n    time.sleep_ms(250)');
    expect(code).toContain('import time');
  });

  it('coerces a non-integer millisecond value to an int', () => {
    const code = generate([
      forever({
        type: 'wait_milliseconds',
        inputs: {
          MS: {
            block: {
              type: 'math_arithmetic',
              fields: { OP: 'DIVIDE' },
              inputs: { A: num(1000), B: num(3) },
            },
          },
        },
      }),
    ]);
    expect(code).toContain('time.sleep_ms(int(1000 / 3))');
  });

  it('generates a for loop with an unused loop variable', () => {
    const code = generate([
      forever({
        type: 'controls_repeat_ext',
        inputs: {
          TIMES: num(3),
          DO: { block: { type: 'onboard_led', fields: { STATE: '0' } } },
        },
      }),
    ]);
    expect(code).toContain(
      ['    for _ in range(3):', '        Pin("LED", Pin.OUT).value(0)'].join('\n'),
    );
  });

  it('generates if / else', () => {
    const code = generate([
      forever({
        type: 'controls_if',
        extraState: { hasElse: true },
        inputs: {
          IF0: { block: { type: 'button_pressed', fields: { PIN: '14' } } },
          DO0: { block: { type: 'onboard_led', fields: { STATE: '1' } } },
          ELSE: { block: { type: 'onboard_led', fields: { STATE: '0' } } },
        },
      }),
    ]);
    expect(code).toContain(
      [
        '    if Pin(14, Pin.IN, Pin.PULL_UP).value() == 0:',
        '        Pin("LED", Pin.OUT).value(1)',
        '    else:',
        '        Pin("LED", Pin.OUT).value(0)',
      ].join('\n'),
    );
  });

  it('increments a variable without importing the numbers module', () => {
    const code = generate(
      [
        forever(
          {
            type: 'math_change',
            fields: { VAR: { id: 'v1' } },
            inputs: { DELTA: num(1) },
          },
          {
            type: 'debug_print',
            inputs: { TEXT: { block: { type: 'variables_get', fields: { VAR: { id: 'v1' } } } } },
          },
        ),
      ],
      undefined,
      [{ name: 'count', id: 'v1' }],
    );
    expect(code).not.toContain('numbers');
    expect(code).toContain('count = 0');
    expect(code).toContain('    count += 1');
    expect(code).toContain('    print(count)');
  });

  it('ignores blocks that are not inside on start or forever', () => {
    const code = generate([
      { type: 'onboard_led', fields: { STATE: '1' } },
      forever({ type: 'onboard_led', fields: { STATE: '0' } }),
    ]);
    expect(code).toBe(
      [
        '# Code automatically generated by PicoBlocks',
        'from machine import Pin',
        '',
        'while True:',
        '    Pin("LED", Pin.OUT).value(0)',
        '',
      ].join('\n'),
    );
  });

  it('generates only the header for an empty workspace', () => {
    expect(generate([])).toBe('# Code automatically generated by PicoBlocks\n');
  });

  it('keeps statements in order down a chain', () => {
    const code = generate([
      forever(
        { type: 'onboard_led', fields: { STATE: '1' } },
        { type: 'wait_seconds', inputs: { SECONDS: num(0.5) } },
        { type: 'onboard_led', fields: { STATE: '0' } },
        { type: 'wait_seconds', inputs: { SECONDS: num(0.5) } },
      ),
    ]);
    expect(code.split('\n').slice(4)).toEqual([
      'while True:',
      '    Pin("LED", Pin.OUT).value(1)',
      '    time.sleep(0.5)',
      '    Pin("LED", Pin.OUT).value(0)',
      '    time.sleep(0.5)',
      '',
    ]);
  });
});
